function startPlayback() {
  initAudio();
  state.isPlaying = true;
  state.nextStep = 0;
  state.nextTime = state.audioCtx.currentTime + 0.04;
  $('#playLabel').textContent = 'Pause loop';
  $('#playIcon').innerHTML = '<path d="M6 5h4v14H6zM14 5h4v14h-4z"/>';
  $('#visualizer').classList.add('live');
  clearInterval(state.timer);
  state.timer = setInterval(() => {
    if (!state.isPlaying || !state.audioCtx) return;
    const bpm = Number($('#tempoRange').value);
    const base = 60 / bpm / 4;
    const swingAmount = Number($('#swingRange').value) / 100;

    while (state.nextTime < state.audioCtx.currentTime + 0.14) {
      const stepIndex = state.nextStep % 16;
      const stepTime = state.nextTime + (stepIndex % 2 === 1 ? base * swingAmount * 0.7 : 0);
      updatePlayhead(stepIndex);
      trackDefs.forEach((track, rowIndex) => {
        const canPlay = state.pattern[rowIndex][stepIndex] && !state.muted.has(track.id) && (!state.solo || state.solo === track.id);
        if (canPlay) {
          playTone(track.type, stepTime, stepIndex);
        }
      });

      const stepLength = base * (stepIndex % 2 === 1 ? 1 + swingAmount * 0.45 : 1 - swingAmount * 0.35);
      state.nextTime += stepLength;
      state.nextStep += 1;
    }

    const bar = String(Math.floor(state.nextStep / 16) + 1).padStart(2, '0');
    const beat = String(Math.floor((state.nextStep % 16) / 4) + 1).padStart(2, '0');
    $('#barDisplay').textContent = `BAR ${bar} : ${beat}`;
  }, 25);
}

function pausePlayback() {
  state.isPlaying = false;
  clearInterval(state.timer);
  state.timer = null;
  updatePlayhead(-1);
  $('#playLabel').textContent = 'Play loop';
  $('#playIcon').innerHTML = '<path d="M7 4.8c0-.8.9-1.3 1.6-.9l11 7.1a1.2 1.2 0 0 1 0 2L8.6 20.1c-.7.4-1.6-.1-1.6-.9V4.8Z"/>';
