function selectPreset(name) {
  state.pattern = clonePattern(presets[name]);
  state.muted.clear();
  state.solo = null;
  renderGrid();
  $$('.preset').forEach((button) => {
    button.classList.toggle('selected', button.dataset.preset === name);
