}

function randomize() {
  state.pattern = trackDefs.map((track, rowIndex) => {
    return Array.from({ length: 16 }, (_, stepIndex) => {
      let chance = [0.23, 0.13, 0.58, 0.2, 0.17][rowIndex];
      if (rowIndex === 0 && stepIndex % 4 === 0) chance = 0.9;
      if (rowIndex === 1 && (stepIndex === 4 || stepIndex === 12)) chance = 0.74;
      if (rowIndex === 2 && stepIndex % 2 === 0) chance = 0.85;
      return Math.random() < chance ? 1 : 0;
    });
  });
  renderGrid();
  markPresetAsCustom();
  saveState();
  showToast('Fresh groove, just for you ✨');
