function clearPattern() {
  state.pattern = trackDefs.map(() => Array(16).fill(0));
  renderGrid();
  markPresetAsCustom();
  saveState();
  showToast('All clear. Start fresh!');
}

function encodeWav(samples, sampleRate) {
  const buffer = new ArrayBuffer(44 + samples.length * 2);
  const view = new DataView(buffer);
  const writeString = (offset, str) => {
    for (let i = 0; i < str.length; i++) {
      view.setUint8(offset + i, str.charCodeAt(i));
    }
  };

  writeString(0, 'RIFF');
  view.setUint32(4, 36 + samples.length * 2, true);
  writeString(8, 'WAVE');
  writeString(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeString(36, 'data');
  view.setUint32(40, samples.length * 2, true);

  let offset = 44;
  for (let i = 0; i < samples.length; i++) {
    const sample = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(offset, sample < 0 ? sample * 0x8000 : sample * 0x7fff, true);
    offset += 2;
  }

  return buffer;
}

function exportLoop() {
  const bpm = Number($('#tempoRange').value);
  const sampleRate = 22050;
  const stepDuration = 60 / bpm / 4;
  const totalSamples = Math.ceil(sampleRate * (16 * stepDuration + 0.35));
  const channel = new Float32Array(totalSamples);

  const addTone = (startIndex, freq, duration, volume, waveform = 'sine') => {
    const oscWave = { sine: 1, triangle: 2, square: 3 };
    const sampleCount = Math.max(1, Math.floor(sampleRate * duration));
    for (let i = 0; i < sampleCount; i++) {
      const time = i / sampleRate;
      const phase = (freq * time) % 1;
      let value = Math.sin(phase * Math.PI * 2);
      if (waveform === 'triangle') value = 2 * Math.abs(2 * phase - 1) - 1;
      const idx = startIndex + i;
      if (idx >= 0 && idx < channel.length) {
        channel[idx] += value * volume * (1 - i / sampleCount);
      }
    }
  };

  for (let stepIndex = 0; stepIndex < 16; stepIndex++) {
    const stepStart = stepIndex * stepDuration;
    const startSample = Math.floor(stepStart * sampleRate);
    trackDefs.forEach((track, rowIndex) => {
      if (!state.pattern[rowIndex][stepIndex]) return;
      if (track.type === 'kick') addTone(startSample, 55, 0.18, 0.85, 'sine');
      if (track.type === 'snare') addTone(startSample, 120, 0.12, 0.4, 'triangle');
      if (track.type === 'hat') addTone(startSample, 5000, 0.04, 0.18, 'sine');
      if (track.type === 'bass') addTone(startSample, [55, 55, 82.41, 73.42, 55, 65.41, 73.42, 82.41, 49, 55, 73.42, 65.41, 49, 55, 82.41, 73.42][stepIndex] * 1.02, 0.22, 0.4, 'triangle');
      if (track.type === 'lead') addTone(startSample, [261.63, 293.66, 329.63, 392.0, 440.0, 392.0, 329.63, 293.66, 261.63, 329.63, 392.0, 440.0, 523.25, 440.0, 392.0, 329.63][stepIndex], 0.22, 0.2, 'sine');
    });
  }

  const wav = encodeWav(channel, sampleRate);
  const blob = new Blob([wav], { type: 'audio/wav' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'loop-lab-export.wav';
  a.click();
  URL.revokeObjectURL(url);
  showToast('Loop exported as WAV');
}

function bindControlEvents() {
  $('#playBtn').addEventListener('click', () => {
    if (state.isPlaying) {
      pausePlayback();
    } else {
