  });

  $('#clearBtn').addEventListener('click', clearPattern);
  $('#randomBtn').addEventListener('click', randomize);
  $('#exportBtn').addEventListener('click', exportLoop);
  $('#helpBtn').addEventListener('click', () => $('#helpModal').classList.add('open'));
  $('#closeHelp').addEventListener('click', () => $('#helpModal').classList.remove('open'));
  $('#helpModal').addEventListener('click', (event) => {
    if (event.target === $('#helpModal')) $('#helpModal').classList.remove('open');
  });

  document.querySelectorAll('.preset').forEach((button) => {
    button.addEventListener('click', () => selectPreset(button.dataset.preset));
  });

  document.addEventListener('keydown', (event) => {
    if (event.code === 'Space') {
      event.preventDefault();
      $('#playBtn').click();
    }
    if (event.key.toLowerCase() === 'r') {
      randomize();
    }
  });

  window.addEventListener('beforeunload', () => {
    if (state.isPlaying) pausePlayback();
  });
}

state.pattern = loadPattern();
updateTempoDisplay();
renderGrid();
bindControlEvents();

if (state.pattern.length && state.pattern[0].length === 16) {
